def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        if isinstance(x, dict):
            if "x" in x and "y" in x:
                return x.get("x", 0), x.get("y", 0)
        return None

    def get_pos(keys, default=(0, 0)):
        for k in keys:
            p = pos(observation.get(k))
            if p is not None:
                return p
        return default

    def nearest(points, sx, sy):
        best = None
        best_d = None
        for item in points or []:
            p = pos(item)
            if p is None:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best_d is None or d < best_d:
                best_d = d
                best = p
        return best

    env = observation.get("environment_name", "") or "resource_collection"
    sx, sy = get_pos(["self_position", "position", "self_pos", "agent_position"])
    ox, oy = get_pos(["opponent_position", "enemy_position", "opponent_pos"], default=(sx, sy))
    gw = observation.get("grid_width", observation.get("width", 0)) or 0
    gh = observation.get("grid_height", observation.get("height", 0)) or 0

    role = observation.get("self_role", observation.get("role", "")) or ""

    if env == "pursuit_evasion":
        if role == "pursuer":
            return [clamp_step(ox - sx), clamp_step(oy - sy)]
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return [clamp_step(target[0] - sx), clamp_step(target[1] - sy)]

    if env == "territory_control":
        targets = (observation.get("unclaimed_cells") or observation.get("opponent_territory") or
                   observation.get("neutral_cells") or observation.get("frontier") or [])
        target = nearest(targets, sx, sy)
