            return [clamp_step(cx - sx), clamp_step(cy - sy)]
        return [clamp_step(sx - ox), clamp_step(sy - oy)]

    resources = (observation.get("resources") or observation.get("resource_positions") or
                 observation.get("resource_cells") or [])
    target = nearest(resources, sx, sy)
    if target is not None:
        return [clamp_step(target[0] - sx), clamp_step(target[1] - sy)]

    # General fallback: prefer moving toward center if known, otherwise toward opponent.
    if gw and gh:
        cx, cy = gw // 2, gh // 2
        # If close to opponent, step away; otherwise drift center.
        if abs(ox - sx) + abs(oy - sy) <= 2:
            return [clamp_step(sx - ox), clamp_step(sy - oy)]
        return [clamp_step(cx - sx), clamp_step(cy - sy)]

